35	/**
36	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total,
37	 * and the sheet's claimed-total, due-total and overdue-total. A change takes a {@link #snapshot} before it and passes it
38	 * to {@link #recordChanges} after its own audit lines, which then records a ROLLUP line for each
39	 * person whose figures moved (people in list order; a person new to the sheet
40	 * counts as moved) and a TOTALS line when any of the sheet's totals moved, then an ALERT line for
41	 * each person whose due-total went from at or below the sheet's alert threshold (or n/a, or new) to
42	 * above it.
43	 */
44	@Service
45	public class RollupService {
46	
47	    /** A person's figures: claimed, due-total held to the sheet's cap (null: n/a), and
48	     *  overdue-total (the dues their overdue counting claims show, n/a ones skipped, not capped). */
49	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
50	        boolean sameAs(Figures other) {
51	            return other != null && claimed.compareTo(other.claimed) == 0
52	                    && Objects.equals(text(dueTotal), text(other.dueTotal))
53	                    && overdueTotal.compareTo(other.overdueTotal) == 0;
54	        }
55	    }
56	
57	    /** The sheet's figures at one moment: each person's, by person id in list order. */
58	    public record Snapshot(Map<Long, Figures> people) {
59	        BigDecimal claimedTotal() {
60	            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
61	        }
62	
63	        /** Everyone's due-total added up, skipping n/a, trimmed. */
64	        BigDecimal dueTotal() {
65	            return trimmedSum(people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).toList());
66	        }
67	
68	        /** Everyone's overdue-total added up, trimmed. */
69	        BigDecimal overdueTotal() {
70	            return trimmedSum(people.values().stream().map(Figures::overdueTotal).toList());
71	        }
72	    }
73	
74	    /** The figures added up, leaving out the single highest and the single lowest when there are
75	     *  three or more. */
76	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
77	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
78	        if (figures.size() < 3) {
79	            return sum;
80	        }
81	        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
82	        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
83	        return sum.subtract(max).subtract(min);
84	    }
