94	    public RollupService(PersonRepository people, ClaimRepository claims, ClaimLogRepository log,
95	            RateChain rateChain, SheetRepository sheets, HistoryService history, Audit audit) {
96	        this.history = history;
97	        this.rateChain = rateChain;
98	        this.people = people;
99	        this.claims = claims;
100	        this.log = log;
101	        this.sheets = sheets;
102	        this.audit = audit;
103	    }
104	
105	    /** The sheet's figures now, as the store (and this transaction) holds them. */
106	    public Snapshot snapshot(String sheetId) {
107	        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
108	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> sheetPeople.put(p.getId(), p));
109	        return snapshotOf(sheets.findById(sheetId), sheetPeople, claims.findBySheetIdOrderByIdDesc(sheetId),
110	                rateChain.levels(sheetId));
111	    }
112	
113	    /** The sheet's figures as it stood at the end of {@code on}, rebuilt from its history (and its
114	     *  ancestors' rates from theirs), with {@code on} as its today. */
115	    public Snapshot snapshotAsOf(String sheetId, LocalDate on) {
116	        HistoryService.AsOf then = history.asOf(sheetId, on);
117	        List<Claim> sheetClaims = then.claims().entrySet().stream()
118	                .sorted(Map.Entry.<Long, Claim>comparingByKey().reversed())
119	                .map(Map.Entry::getValue)
120	                .toList();
121	        RateChain.Levels sheetRates = new RateChain.Levels(sheetId, then.rates(),
122	                rateChain.ancestors(sheetId).stream().map(a -> history.asOf(a, on).rates()).toList());
123	        return snapshotOf(Optional.of(then.sheet()), then.people(), sheetClaims, sheetRates);
124	    }
125	
126	    /** The figures of a sheet with these settings (none: the defaults, today the real date), people
127	     *  (by id, in list order), claims (newest first) and rates. */
128	    private static Snapshot snapshotOf(Optional<Sheet> sheet, Map<Long, Person> sheetPeople, List<Claim> sheetClaims,
129	            RateChain.Levels sheetRates) {
130	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
131	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
132	        BigDecimal cap = sheet.map(Sheet::getCap).orElse(null);
133	        LateCharge late = LateCharge.of(sheet);
134	        Map<Long, Person> held = new LinkedHashMap<>();
135	        sheetPeople.forEach((id, p) -> {
136	            if (p.isHeld() || p.isRetired()) {
137	                held.put(id, p);
138	            }
139	        });
140	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
141	        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
142	        Map<Long, BigDecimal> claimedBy = new LinkedHashMap<>();
143	        for (Claim c : sheetClaims) {
144	            if (counts(c, held, today)) {
145	                counted.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
146	            }
147	            if (countsClaimed(c, held.get(c.getPersonId()), today) && !isCorrection(c)) {
148	                claimedBy.merge(c.getPersonId(), c.getAmount(), BigDecimal::add);
149	            }
150	        }
151	        Map<Long, Figures> out = new LinkedHashMap<>();
152	        sheetPeople.forEach((id, p) -> {
153	            List<Claim> theirs = counted.getOrDefault(id, List.of());
154	            BigDecimal claimed = zero().add(claimedBy.getOrDefault(id, zero()));
155	            BigDecimal overdue = theirs.stream()
156	                    .filter(c -> c.getStatus().isOpen() && late.isPast(c, p))
157	                    .map(c -> shownDueOf(c, p, sheetRates, floor, late, rounding))
158	                    .filter(Objects::nonNull)
159	                    .reduce(zero(), BigDecimal::add);
160	            out.put(id, new Figures(p.getName(), claimed,
161	                    Sheet.capped(dueTotalOf(theirs, p, sheetRates, today, floor, late, rounding), cap), overdue));
162	        });
163	        return new Snapshot(out);
164	    }
