171	    /** The sheet's own figures as it is now, or as it stood at the end of {@code asOf} when given:
172	     *  how many people (retired ones too), and the due-total and overdue-total it shows. */
173	    public Consolidated own(String sheetId, LocalDate asOf) {
174	        Snapshot figures = asOf == null ? snapshot(sheetId) : snapshotAsOf(sheetId, asOf);
175	        return new Consolidated(figures.people().size(), figures.dueTotal(), figures.overdueTotal());
176	    }
