178	    /** The figures of the sheet's descendants (its children, theirs, and so on), each sheet's as
179	     *  it is now, or as it stood at the end of {@code asOf} when given, added up; all zero for a
180	     *  sheet with no children. */
181	    public Consolidated descendants(String sheetId, LocalDate asOf) {
182	        int count = 0;
183	        BigDecimal due = zero();
184	        BigDecimal overdue = zero();
185	        Set<String> seen = new HashSet<>(Set.of(sheetId));
186	        ArrayDeque<String> todo = new ArrayDeque<>(List.of(sheetId));
187	        while (!todo.isEmpty()) {
188	            for (Sheet child : sheets.findByParentOrderByIdAsc(todo.poll())) {
189	                if (!seen.add(child.getId())) {
190	                    continue;
191	                }
192	                todo.add(child.getId());
193	                Snapshot figures = asOf == null ? snapshot(child.getId()) : snapshotAsOf(child.getId(), asOf);
194	                count += figures.people().size();
195	                due = due.add(figures.dueTotal());
196	                overdue = overdue.add(figures.overdueTotal());
197	            }
198	        }
199	        return new Consolidated(count, due, overdue);
200	    }
