202	    /** Each person's due-total for the period from {@code from} to {@code to}, inclusive, by person
203	     *  id, for everyone on the sheet: the dues (n/a ones skipped) their claims due inside it show
204	     *  now, counting each by the status its log gives it at the end of {@code to} (OPEN and SETTLED
205	     *  ones count; one added after then does not; OPEN ones within a hold of their person, unbound,
206	     *  or deferred, left out). */
207	    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
208	        Optional<Sheet> sheet = sheets.findById(sheetId);
209	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
210	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
211	        LateCharge late = LateCharge.of(sheet);
212	        RateChain.Levels sheetRates = rateChain.levels(sheetId);
213	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
214	        Map<Long, Person> held = heldPeople(sheetPeople);
215	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, p -> p));
216	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
217	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
218	        Map<Long, BigDecimal> out = new LinkedHashMap<>();
219	        for (Person p : sheetPeople) {
220	            out.put(p.getId(), zero());
221	        }
222	        Map<Long, ClaimStatus> statusAtEnd = statusesOn(sheetId, to);
223	        sheetClaims.stream()
224	                .filter(c -> countsAt(c, statusAtEnd.containsKey(c.getId()) ? statusAtEnd.get(c.getId()) : c.getStatus(),
225	                        held, today))
226	                .filter(c -> !c.getDueBy().isBefore(from) && !c.getDueBy().isAfter(to))
227	                .filter(c -> byId.containsKey(c.getPersonId()))
228	                .forEach(c -> {
229	                    BigDecimal due = shownDueOf(c, byId.get(c.getPersonId()), sheetRates, floor, late, rounding);
230	                    if (due != null) {
231	                        out.merge(c.getPersonId(), due, BigDecimal::add);
232	                    }
233	                });
234	        return out;
235	    }
236	
237	    /** Each person's carried figure for the period from {@code from} to {@code to}, by person id,
238	     *  for everyone on the sheet: the dues (n/a ones skipped) their claims show now whose due-by
239	     *  falls in another of the sheet's periods ({@code periodEndOn} gives the to-date of the period
240	     *  containing a date, null outside every one) ending before {@code from}, and that were still
241	     *  OPEN or PENDING at the end of {@code to} by their log, counted as {@link #dueByPersonBetween}
242	     *  counts them. */
243	    public Map<Long, BigDecimal> carriedByPersonInto(String sheetId, LocalDate from, LocalDate to,
244	            Function<LocalDate, LocalDate> periodEndOn) {
245	        Optional<Sheet> sheet = sheets.findById(sheetId);
246	        LocalDate today = sheet.map(Sheet::getToday).orElseGet(LocalDate::now);
247	        Function<LocalDate, BigDecimal> floor = floorOf(sheet);
248	        LateCharge late = LateCharge.of(sheet);
249	        RateChain.Levels sheetRates = rateChain.levels(sheetId);
250	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
251	        Map<Long, Person> held = heldPeople(sheetPeople);
252	        Map<Long, Person> byId = sheetPeople.stream().collect(Collectors.toMap(Person::getId, p -> p));
253	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
254	        Function<Claim, RoundingMode> rounding = roundingOf(sheet, sheetClaims);
255	        Map<Long, BigDecimal> out = new LinkedHashMap<>();
256	        for (Person p : sheetPeople) {
257	            out.put(p.getId(), zero());
258	        }
259	        Map<Long, ClaimStatus> statusAtEnd = statusesOn(sheetId, to);
260	        sheetClaims.stream()
261	                .filter(c -> byId.containsKey(c.getPersonId()))
262	                .filter(c -> {
263	                    LocalDate ownEnd = periodEndOn.apply(c.getDueBy());
264	                    return ownEnd != null && ownEnd.isBefore(from);
265	                })
266	                .filter(c -> {
267	                    ClaimStatus status = statusAtEnd.containsKey(c.getId()) ? statusAtEnd.get(c.getId()) : c.getStatus();
268	                    return status != null && status.isOpen() && countsAt(c, status, held, today);
269	                })
270	                .forEach(c -> {
271	                    BigDecimal due = shownDueOf(c, byId.get(c.getPersonId()), sheetRates, floor, late, rounding);
272	                    if (due != null) {
273	                        out.merge(c.getPersonId(), due, BigDecimal::add);
274	                    }
275	                });
276	        return out;
277	    }
278	
279	    /** A statement's figures for a person: their claims that count, each with the figure a statement
280	     *  binds it to (null: n/a), and their due-total held to the cap (null: n/a). */
281	    public record Stated(Map<Claim, BigDecimal> counted, BigDecimal dueTotal) {
282	    }
283	
284	    /** The statement of a person on a sheet that is not stored (one rebuilt as it stood at the end of
285	     *  a date, its today that date): counting their claims among {@code sheetClaims}, by the rates,
286	     *  floor, late charge and cap of the sheet and the person's holds and retirement, as the live
287	     *  totals do. */
288	    public static Stated statedOn(Sheet sheet, Person person, Long personId, List<Claim> sheetClaims,
289	            RateChain.Levels sheetRates) {
290	        Optional<Sheet> held = Optional.of(sheet);
291	        LocalDate today = sheet.getToday();
292	        Function<LocalDate, BigDecimal> floor = floorOf(held);
293	        LateCharge late = LateCharge.of(held);
294	        Function<Claim, RoundingMode> rounding = roundingOf(held, sheetClaims);
295	        Map<Claim, BigDecimal> counted = new LinkedHashMap<>();
296	        sheetClaims.stream()
297	                .filter(c -> c.getPersonId().equals(personId) && countsFor(c, person, today))
298	                .forEach(c -> counted.put(c, shownDueOf(c, person, sheetRates, floor, late, rounding)));
299	        BigDecimal dueTotal = dueTotalOf(List.copyOf(counted.keySet()), person, sheetRates, today, floor, late, rounding);
300	        return new Stated(counted, Sheet.capped(dueTotal, sheet.getCap()));
301	    }
302	
303	    /** The due a claim of a person shows on a sheet that is not stored (one rebuilt as it stood at
304	     *  the end of a date, its today that date), among {@code sheetClaims}, by the rates, floor and
305	     *  late charge of that sheet, as the live figures show it (null: n/a). */
306	    public static BigDecimal dueOn(Sheet sheet, Person person, Claim claim, List<Claim> sheetClaims,
307	            RateChain.Levels sheetRates) {
308	        Optional<Sheet> held = Optional.of(sheet);
309	        return shownDueOf(claim, person, sheetRates, floorOf(held), LateCharge.of(held), roundingOf(held, sheetClaims));
310	    }
311	
312	    /** Keep on each person a snapshot line for {@code day} (the day being left) with their
313	     *  due-total in {@code before}, and record, once the transaction commits, a SNAPSHOT line for
314	     *  each (in list order). */
315	    public void recordSnapshot(String sheetId, String user, LocalDate day, Snapshot before) {
316	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
317	                .collect(Collectors.toMap(Person::getId, p -> p));
318	        before.people().forEach((id, p) -> {
319	            Person person = byId.get(id);
320	            if (person != null) {
321	                person.addSnapshot(day, p.dueTotal() == null ? null : p.dueTotal().setScale(2));
322	            }
323	            audit.recordOnCommit("SNAPSHOT sheet=" + sheetId + " by=" + user
324	                    + " name=" + p.name() + " due-total=" + text(p.dueTotal()));
325	        });
326	        people.flush();
327	    }
328	
329	    /** Record, once the transaction commits, a ROLLUP line for each person whose figures moved
330	     *  since {@code before}, then a TOTALS line when the sheet's totals moved. */
331	    public void recordChanges(String sheetId, String user, Snapshot before) {
332	        recordChanges(sheetId, user, before, false);
333	    }
334	
335	    private void recordChanges(String sheetId, String user, Snapshot before, boolean totals) {
336	        Snapshot after = snapshot(sheetId);
337	        after.people().forEach((id, now) -> {
338	            if (!now.sameAs(before.people().get(id))) {
339	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
340	                        + " claimed=" + text(now.claimed()) + " due-total=" + text(now.dueTotal()) + " overdue-total=" + text(now.overdueTotal()));
341	            }
342	        });
343	        if (totals || after.claimedTotal().compareTo(before.claimedTotal()) != 0
344	                || after.dueTotal().compareTo(before.dueTotal()) != 0
345	                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
346	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total="
347	                    + text(after.claimedTotal()) + " due-total=" + text(after.dueTotal())
348	                    + " overdue-total=" + text(after.overdueTotal()));
349	        }
350	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
351	        if (threshold != null) {
352	            after.people().forEach((id, now) -> {
353	                Figures was = before.people().get(id);
354	                if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
355	                    audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + now.name()
356	                            + " due-total=" + text(now.dueTotal()));
357	                }
358	            });
359	        }
360	    }
361	
362	    /** Whether a due-total (null: n/a) is above the alert threshold. */
363	    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
364	        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
365	    }
366	
367	    /** Record, once the transaction commits, a ROLLUP line for every person (in list order), then
368	     *  the sheet's TOTALS line, as the sheet's figures are now. */
369	    public void recordAll(String sheetId, String user) {
370	        recordChanges(sheetId, user, new Snapshot(Map.of()), true);
371	    }
372	
373	    /** Whether a claim counts toward due totals: only OPEN (or PENDING) and SETTLED ones
374	     *  do, but not (unless bound by a statement) any open one of a person (by id in {@code held})
375	     *  whose retirement date the sheet's
376	     *  today has reached, nor one deferred on the sheet's today. */
377	    private static boolean counts(Claim c, Map<Long, Person> held, LocalDate today) {
378	        return countsFor(c, held.get(c.getPersonId()), today);
379	    }
380	
381	    /** Whether a claim of the person (null: one with neither a hold nor a retirement) counts, as
382	     *  {@link #counts} has it. */
383	    private static boolean countsFor(Claim c, Person person, LocalDate today) {
384	        if (c.getStatus() == ClaimStatus.SETTLED) {
385	            return true;
386	        }
387	        if (!c.getStatus().isOpen() || c.isDeferredOn(today)) {
388	            return false;
389	        }
390	        return c.isBound() || !leftOut(person, c, today);
391	    }
392	
393	    /** Whether a claim counts toward claimed: as {@link #countsFor} has it. */
394	    private static boolean countsClaimed(Claim c, Person person, LocalDate today) {
395	        if (c.getStatus() == ClaimStatus.SETTLED) {
396	            return true;
397	        }
398	        if (!c.getStatus().isOpen() || c.isDeferredOn(today)) {
399	            return false;
400	        }
401	        return c.isBound() || person == null || !person.retiredOn(today);
402	    }
403	
404	    /** Whether a claim counts toward a period's due-total, taken in {@code status} (the one it had
405	     *  at the period's end; null when it was not yet added then): as {@link #counts} has it. */
406	    private static boolean countsAt(Claim c, ClaimStatus status, Map<Long, Person> held, LocalDate today) {
407	        if (status == null) {
408	            return false;
409	        }
410	        if (status == ClaimStatus.SETTLED) {
411	            return true;
412	        }
413	        if (!status.isOpen() || c.isDeferredOn(today)) {
414	            return false;
415	        }
416	        // a reached retirement leaves out a claim still open now, as the live due-total does
417	        return !c.getStatus().isOpen() || c.isBound() || !leftOut(held.get(c.getPersonId()), c, today);
418	    }
419	
420	    /** The status each of the sheet's claims had at the end of {@code on}, by claim id, as their
421	     *  status logs record it (null for a claim not yet added then); a claim with no log at all is
422	     *  left out, taken in its status now. */
423	    private Map<Long, ClaimStatus> statusesOn(String sheetId, LocalDate on) {
424	        Map<Long, ClaimStatus> out = new LinkedHashMap<>();
425	        for (ClaimLog line : log.findBySheetIdOrderByIdAsc(sheetId)) {
426	            ClaimStatus before = out.get(line.getClaimId());
427	            out.put(line.getClaimId(), line.getOn().isAfter(on) ? before : line.getStatus());
428	        }
429	        return out;
430	    }
431	
432	    /** Whether an unbound open claim of the person (null: one with neither a hold nor a retirement)
433	     *  is left out of the live totals: their retirement date reached on the sheet's today. A hold
434	     *  (the claim's or its person's) leaves nothing out; it only takes the person out of pool cuts. */
435	    private static boolean leftOut(Person person, Claim c, LocalDate today) {
436	        return person != null && person.retiredOn(today);
437	    }
438	
439	    /** The people with a hold or a retirement date, by id. */
440	    private static Map<Long, Person> heldPeople(List<Person> sheetPeople) {
441	        return sheetPeople.stream().filter(p -> p.isHeld() || p.isRetired()).collect(Collectors.toMap(Person::getId, p -> p));
442	    }
443	
444	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
445	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
446	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
447	    private static BigDecimal dueTotalOf(List<Claim> counted, Person person, RateChain.Levels sheetRates, LocalDate today,
448	            Function<LocalDate, BigDecimal> floor, LateCharge late, Function<Claim, RoundingMode> rounding) {
449	        List<BigDecimal> dues = counted.stream()
450	                .map(c -> shownDueOf(c, person, sheetRates, floor, late, rounding))
451	                .filter(Objects::nonNull)
452	                .toList();
453	        if (inForce(person, sheetRates.inForce(), today).isEmpty() && dues.isEmpty()) {
454	            return null;
455	        }
456	        return dues.stream().reduce(zero(), BigDecimal::add);
457	    }
458	
459	    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
460	     *  to (null: n/a), late charge included, else its amount times the rate in force on its date of its person's grade
461	     *  then (as the claim applies the rates: not a forward-only one saved after it was added), rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a
462	     *  correction's never is), with the late charge worked out on that floored figure on top. */
463	    private static BigDecimal shownDueOf(Claim c, Person person, RateChain.Levels sheetRates, Function<LocalDate, BigDecimal> floor,
464	            LateCharge late, Function<Claim, RoundingMode> rounding) {
465	        if (c.getSettledDue() != null) {
466	            return c.getSettledDue();
467	        }
468	        if (c.isBound()) {
469	            return c.getStatedDue();
470	        }
471	        RoundingMode mode = rounding.apply(c);
472	        BigDecimal figure = figureOf(c, person, sheetRates, mode);
473	        BigDecimal floored = figure == null || c.isCorrection() ? figure : figure.max(floor.apply(c.getDate()));
474	        return late.addTo(c, person, floored, mode);
475	    }
476	
477	    /** A claim's rate figure before any late charge or floor. */
478	    private static BigDecimal figureOf(Claim c, Person person, RateChain.Levels sheetRates, RoundingMode mode) {
479	        return inForce(person, sheetRates.forClaim(c.getAdded()), c.getDate())
480	                .map(r -> c.getAmount().multiply(r.getPct()).divide(BigDecimal.valueOf(100), 2, mode))
481	                .orElse(null);
482	    }
483	
484	    /** How each claim's live figures round: by the sheet's policy date against its date, or for a
485	     *  correction the date of the claim (of the same person) it corrects. */
486	    private static Function<Claim, RoundingMode> roundingOf(Optional<Sheet> sheet, List<Claim> sheetClaims) {
487	        Rounding rounding = Rounding.of(sheet);
488	        Map<String, LocalDate> numbered = new LinkedHashMap<>();
489	        for (Claim c : sheetClaims) {
490	            if (c.getNumber() != null) {
491	                numbered.putIfAbsent(c.getPersonId() + "/" + c.getNumber(), c.getDate());
492	            }
493	        }
494	        return c -> rounding.on(c.getCorrects() == null ? c.getDate()
495	                : numbered.getOrDefault(c.getPersonId() + "/" + c.getCorrects(), c.getDate()));
496	    }
497	
498	    /** The rate in force on a date for the person's grade in force then; none when that one's
499	     *  to-date has passed by then. */
500	    private static Optional<Rate> inForce(Person person, List<Rate> sheetRates, LocalDate on) {
501	        String grade = person.gradeOn(on);
502	        return sheetRates.stream()
503	                .filter(r -> r.getGrade().equals(grade) && r.appliesOn(on))
504	                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
505	                .filter(r -> r.runsThrough(on));
506	    }
507	
508	    /** The sheet's floor in force on each date. */
509	    private static Function<LocalDate, BigDecimal> floorOf(Optional<Sheet> sheet) {
510	        return on -> sheet.map(s -> s.floorOn(on)).orElse(Sheet.DEFAULT_FLOOR);
511	    }
512	
513	    private static BigDecimal zero() {
514	        return BigDecimal.ZERO.setScale(2);
515	    }
516	
517	    /** A figure as the screen shows it: two decimals, or n/a. */
518	    public static String text(BigDecimal value) {
519	        return value == null ? "n/a" : value.setScale(2).toPlainString();
520	    }
521	
522	    /** Whether a claim corrects another: claimed leaves such claims out. */
523	    private static boolean isCorrection(Claim c) {
524	        return c.getCorrects() != null && !c.getCorrects().isBlank();
525	    }
526	}
