1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Injectable, inject } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session, otherError } from '../../core/session';
5	import type { Person } from '../people/people-api';
6	
7	/** An amount of 0.00 or more with up to two decimals. */
8	export const AMOUNT_PATTERN = /^\d{1,13}(\.\d{1,2})?$/;
9	
10	/** A claim form's amount: up to two decimals, negative for a correction. */
11	export const CLAIM_AMOUNT_PATTERN = /^-?\d{1,13}(\.\d{1,2})?$/;
12	
13	/** DRAFT when added, then OPEN, then SETTLED; a clerk settling one above the clerk limit sends it to
14	 *  PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or PENDING
15	 *  claim may be VOID, and a steward may void a SETTLED one within 7 days of its settlement. A DRAFT
16	 *  claim may be DELETED (counting nowhere) and restored to DRAFT on the sheet's today it was deleted.
17	 *  A claim whose due is above the review threshold goes to REVIEW (counting nowhere, unnumbered)
18	 *  when opened, until a steward reviews it (OPEN); a REVIEW claim may be VOID. */
19	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
20	
21	/** A move of a claim's status, as the server names it. */
22	export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'review' | 'resettle' | 'delete' | 'restore';
23	
24	export interface Claim {
25	  id: number;
26	  /** What the claim was added as against a forward-only rate's mark: its own id, or for a copy in a
27	   *  clone the claim it copies was added as. */
28	  added: number;
29	  personId: number;
30	  /** Always with two decimals, as the server formats it. */
31	  amount: string;
32	  date: string;
33	  note: string;
34	  status: ClaimStatus;
35	  /** The sheet's number for the claim, given when it is opened and kept if it is voided; null while DRAFT.
36	   *  A sheet-wide number, or under period numbering one within its period (P1-1, X-1 in no period). */
37	  number: string | null;
38	  /** The due fixed when the claim was settled, with two decimals; null, so the due is live, for
39	   *  a claim not SETTLED or settled when its grade had no rate. */
40	  settledDue: string | null;
41	  /** The user who opened the claim, who cannot settle it; null while DRAFT. */
42	  openedBy: string | null;
43	  /** The user who last edited the claim, who like its opener cannot settle or approve it; null
44	   *  when never edited. */
45	  editedBy: string | null;
46	  /** Whether the person's last statement bound the claim: it then shows and totals statedDue
47	   *  (a PENDING one too). */
48	  stated: boolean;
49	  /** The due the claim was bound to, with two decimals; null when unbound or n/a then. */
50	  statedDue: string | null;
51	  /** The number of the SETTLED claim this correction (a negative amount) corrects; null for others. */
52	  corrects: string | null;
53	  /** Where the claim is listed, newest (highest) first: set when it is added, and again when it
54	   *  is reassigned, so a moved claim is its new person's newest. */
55	  listed: number;
56	  /** yyyy-mm-dd: fixed when the claim was created, its date plus its person's own terms, else
57	   *  their grade's, else the sheet's, each in force on the sheet's today when it was created; later changes to the terms or its date leave it. */
58	  dueBy: string;
59	  /** The claim's status log, oldest first: one line per status it has had. */
60	  log: ClaimLogLine[];
61	  /** yyyy-mm-dd: the date the claim was deferred until; null when it was never deferred. */
62	  deferredUntil: string | null;
63	  /** How many proofs the claim has. */
64	  proofs: number;
65	  /** Of the claim's proofs, how many are receipts. */
66	  receiptProofs: number;
67	  /** Of the claim's proofs, how many are photos. */
68	  photoProofs: number;
69	  /** The number of the claim this one was split from; null when not made by a split. */
70	  splitFrom: string | null;
71	  /** The user whose open editor locks the claim for everyone else; null while unlocked. */
72	  lockedBy: string | null;
73	  /** Whether the claim was added while its period was soft-closed. */
74	  lateEntry: boolean;
75	  /** yyyy-mm-dd: the last day (the sheet's today then) the claim was reminded; null when never reminded. */
76	  reminded: string | null;
77	  /** Whether a steward waived the claim's late charge: it bears none from then on. */
78	  waived: boolean;
79	  /** Whether the claim is held: held and open, unless bound by a statement, it counts in no live total. */
80	  held: boolean;
81	  /** yyyy-mm-dd: the claim's review day (the sheet's today when it went to REVIEW); null when it never did. */
82	  reviewOn: string | null;
83	  /** The claim's external reference, unique on its sheet without regard to case; null when none. */
84	  ref: string | null;
85	  /** The claim's tags: lower-case, sorted and comma separated; null when none. */
86	  tags: string | null;
87	  /** The reason a VOID claim was voided with, from the sheet's list; null when none. */
88	  voidReason: string | null;
89	  /** The comments on the claim, oldest first. */
90	  comments: ClaimComment[];
91	  /** The claim's lines, in the order added; with lines its amount is their total. */
92	  lines: ClaimLine[];
93	  /** The number of the bulk settle batch that settled the claim (or sent it to PENDING); null
94	   *  when it was settled one at a time or not at all. */
95	  batch: number | null;
96	}
97	
98	/** A comment on a claim: who wrote it, the sheet's today then (yyyy-mm-dd), and its text. */
99	export interface ClaimComment {
100	  by: string;
101	  on: string;
102	  text: string;
103	}
104	
105	/** A comment as the screen shows it: <user> on <date>: <text>. */
106	export function commentText(c: ClaimComment): string {
107	  return `${c.by} on ${c.on}: ${c.text}`;
108	}
109	
110	/** A line of a claim: a label, a whole quantity of at least 1 and a unit amount with two decimals. */
111	export interface ClaimLine {
112	  label: string;
113	  qty: number;
114	  unit: string;
115	}
116	
117	/** A claim line as the screen shows it: <label> <qty> x <unit>. */
118	export function lineText(l: ClaimLine): string {
119	  return `${l.label} ${l.qty} x ${l.unit}`;
120	}
121	
122	/** A line of a claim's status log: the status, who moved the claim there, the sheet's today then
123	 *  (yyyy-mm-dd), and the claim's due at that moment with two decimals (null: n/a). */
124	export interface ClaimLogLine {
125	  status: ClaimStatus;
126	  by: string;
127	  on: string;
128	  due: string | null;
129	}
130	
131	/** A status log line as the screen shows it: <STATUS> by <user> on <date> due=<due>. */
132	export function logLineText(l: ClaimLogLine): string {
133	  return `${l.status} by ${l.by} on ${l.on} due=${l.due ?? 'n/a'}`;
134	}
135	
136	/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it; null
137	 *  when it was not yet added then. A claim with no log at all is taken in its status now. */
138	export function statusOn(c: Claim, day: string): ClaimStatus | null {
139	  if (c.log.length === 0) return c.status;
140	  let status: ClaimStatus | null = null;
141	  for (const l of c.log) {
142	    if (l.on <= day) status = l.status;
143	  }
144	  return status;
145	}
146	
147	/** Claims as they are listed: newest (or most recently reassigned) first. */
148	export function byListed(a: Claim, b: Claim): number {
149	  return b.listed - a.listed;
150	}
151	
152	/** Whether a claim is a correction: its amount is negative. */
153	export function isCorrection(c: Claim): boolean {
154	  return c.amount.startsWith('-');
155	}
156	
157	/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN one). */
158	export function isOpen(c: Claim): boolean {
159	  return c.status === 'OPEN' || c.status === 'PENDING';
160	}
161	
162	/** Whether a claim's due is bound to statedDue: stated (a PENDING claim too). */
163	export function isBound(c: Claim): boolean {
164	  return c.stated;
165	}
166	
167	/** Whether a claim is deferred on the sheet's today: OPEN, deferred until a date after it. Until
168	 *  then it counts in no total, is not overdue and cannot be settled. */
169	export function deferred(c: Claim, today: string | null): boolean {
170	  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
171	}
172	
173	/** Whether a claim counts toward claimed and due totals on the sheet's today: only open (OPEN or
174	 *  PENDING) and SETTLED ones do, but not a deferred one. */
175	export function counts(c: Claim, today: string | null): boolean {
176	  return (isOpen(c) || c.status === 'SETTLED') && !deferred(c, today);
177	}
178	
179	/** A claim's due-by (yyyy-mm-dd), fixed when it was created. */
180	export function dueBy(c: Claim): string {
181	  return c.dueBy;
182	}
183	
184	/** The date a claim is overdue after: its due-by plus the grace days of its person's grade in
185	 *  force on its date (0: none). */
186	export function lateFrom(c: Claim, grace = 0): string {
187	  return grace === 0 ? dueBy(c) : plusDays(dueBy(c), grace);
188	}
189	
190	/** Whether a claim is overdue: open (OPEN or PENDING), not deferred, with its due-by plus its
191	 *  grace days before the sheet's today. */
192	export function overdue(c: Claim, today: string | null, grace = 0): boolean {
193	  return isOpen(c) && today !== null && lateFrom(c, grace) < today && !deferred(c, today);
194	}
195	
196	/** Whether a claim is late for review: it is REVIEW and its review day plus the sheet's review
197	 *  SLA in days (null: none, never late) is before the sheet's today. */
198	export function reviewLate(c: Claim, today: string | null, sla: number | null): boolean {
199	  return c.status === 'REVIEW' && sla !== null && today !== null && c.reviewOn !== null
200	    && plusDays(c.reviewOn, sla) < today;
201	}
202	
203	/** A date (yyyy-mm-dd) moved on by whole days. */
204	export function plusDays(date: string, days: number): string {
205	  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
206	}
207	
208	/** Whether a claim's live figures round half up: by the sheet's rounding mode in force on its date
209	 *  (a correction's, the date of the claim of its person it corrects, among `theirs`) when there is
210	 *  one; else when that date is before the sheet's policy date (null: blank, the sheet's today),
211	 *  rounding half to even otherwise. */
212	export function roundsHalfUp(c: Claim, theirs: readonly Claim[], policyDate: string | null, today: string | null,
213	                             roundingOn: (date: string) => string | null = () => null): boolean {
214	  const on = c.corrects === null ? c.date : theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
215	  const mode = roundingOn(on);
216	  if (mode === 'half-up') return true;
217	  if (mode === 'half-even') return false;
218	  const policy = policyDate ?? today;
219	  if (policy === null) return false;
220	  return on < policy;
221	}
222	
223	export interface ClaimForm {
224	  amount: string;
225	  /** null takes the sheet's today. */
226	  date: string | null;
227	  note: string;
228	  /** The number of the claim a correction corrects; null when none is named. */
229	  corrects: string | null;
230	  /** The claim's external reference; null (or blank) for none. */
231	  ref: string | null;
232	  /** The claim's tags, comma separated; null (or blank) for none. */
233	  tags: string | null;
234	}
235	
236	export interface QuickAddForm {
237	  name: string;
238	  amount: string;
239	}
240	
241	/** A quick-add's result: the person (just added when personAdded) and their new DRAFT claim. */
242	export interface QuickAdd {
243	  person: Person;
244	  personAdded: boolean;
245	  claim: Claim;
246	}
247	
248	// The claims kept on the active sheet, read and written through the server.
249	@Injectable({ providedIn: 'root' })
250	export class ClaimsApi {

