          <button type="button" data-testid="claim-comment-add" (click)="comment(c)"
            [attr.aria-label]="'Comment on claim of ' + c.amount + ' on ' + c.date">Add comment</button>
          <ol [attr.aria-label]="'Lines of claim of ' + c.amount + ' on ' + c.date">
            @for (l of c.lines; track $index) {
              <li data-testid="claim-lines-line">{{ lineText(l) }}</li>
            }
          </ol>
          <label [for]="'claim-line-label-' + c.id">Line label</label>
          <input [id]="'claim-line-label-' + c.id" data-testid="claim-line-label" autocomplete="off"
            [value]="lineDrafts()[c.id]?.label ?? ''" (input)="lineChanged(c.id, 'label', $any($event.target).value)" />
          <label [for]="'claim-line-qty-' + c.id">Quantity</label>
          <input [id]="'claim-line-qty-' + c.id" data-testid="claim-line-qty" inputmode="numeric" autocomplete="off"
            [value]="lineDrafts()[c.id]?.qty ?? ''" (input)="lineChanged(c.id, 'qty', $any($event.target).value)" />
          <label [for]="'claim-line-unit-' + c.id">Unit amount</label>
          <input [id]="'claim-line-unit-' + c.id" data-testid="claim-line-unit" inputmode="decimal" autocomplete="off"
            [value]="lineDrafts()[c.id]?.unit ?? ''" (input)="lineChanged(c.id, 'unit', $any($event.target).value)" />
          <button type="button" data-testid="claim-line-add" (click)="addLine(c)"
            [attr.aria-label]="'Add a line to claim of ' + c.amount + ' on ' + c.date">Add line</button>
          <button type="button" data-testid="claim-open" (click)="changeStatus(c, 'open')"
            [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
          <label [for]="'claim-settle-date-' + c.id">Settle as of (blank: now)</label>
          <input [id]="'claim-settle-date-' + c.id" type="date" data-testid="claim-settle-date"
            [value]="settleDates()[c.id] ?? ''" (input)="settleDateChanged(c.id, $any($event.target).value)" />
          <button type="button" data-testid="claim-settle" (click)="settle(c)"
            [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
          <label [for]="'claim-proof-kind-' + c.id">Proof kind (none chosen: receipt)</label>
          <select [id]="'claim-proof-kind-' + c.id" data-testid="claim-proof-kind"
            [value]="proofKinds()[c.id] ?? ''" (change)="proofKindChanged(c.id, $any($event.target).value)">
            <option value="">(none chosen)</option>
            @for (k of PROOF_KINDS; track k) {
              <option [value]="k">{{ k }}</option>
            }
          </select>
          <button type="button" data-testid="claim-proof" (click)="addProof(c)"
            [attr.aria-label]="'Add a proof to claim of ' + c.amount + ' on ' + c.date">Add proof</button>
          <button type="button" data-testid="claim-remind" (click)="remind(c)"
            [attr.aria-label]="'Remind claim of ' + c.amount + ' on ' + c.date">Remind</button>
          <button type="button" data-testid="claim-waive" (click)="waive(c)"
            [attr.aria-label]="'Waive the late charge of claim of ' + c.amount + ' on ' + c.date">Waive late charge</button>
          <button type="button" data-testid="claim-hold" (click)="toggleHold(c)"
  });
  // A change of the sheet's today releases every lock, so an open editor closes.
  let today: string | null | undefined;
  effect(() => {
    const now = this.session.today();
    if (today !== undefined && now !== today) untracked(() => this.reset());
    today = now;
  });
}

/** The claim's figure (its amount times the rate in force on the claim's date for the person's grade then (not a forward-only
 *  one saved after the claim was added), divided by 100, rounded
 *  by the claim's rounding policy (half up before the sheet's policy date, else half to even), or the figure a statement
 *  bound it to), with its late charge on top when it is an overdue open (OPEN or PENDING) claim, then raised to the
 *  sheet's floor in force on its date; n/a with no rate in force then. A claim settled with a due shows the due fixed then. */
protected dueOf(c: Claim): string {
  const grade = gradeOn(this.grades(), c.date);
  const due = claimDueCents(this.rates().forClaim(c.added).filter((r) => r.grade === grade), c, cents(this.session.floorOn(c.date)), {
    today: this.session.today(), latePctOn: (d) => this.session.latePctOn(d), graceOf: (o) => this.graceOf(o),
  }, roundsHalfUp(c, this.claims(), this.session.policyDate(), this.session.today(), (d) => this.session.roundingOn(d)));
  return due === null ? 'n/a' : money(due);
}

/** A line of the claim's status log as the screen shows it. */
protected logText(l: ClaimLogLine): string {
  return logLineText(l);
}

/** The claim's due-by, fixed when it was created. */
protected dueByOf(c: Claim): string {
  return dueBy(c);
}

/** Whether the claim is open (OPEN or PENDING) with its due-by plus its grace days before the sheet's today. */
protected overdueOf(c: Claim): boolean {
  return overdue(c, this.session.today(), this.graceOf(c));
}

/** The claim's grace days: those of the person's grade in force on its date. */
private graceOf(c: Claim): number {
  return this.session.graceOn(gradeOn(this.grades(), c.date), c.date);
}

