  protected readonly dueByPeriod = computed(() => {
    const out = new Map<number, number>();
    for (const period of this.periods()) {
      out.set(period.id, this.people().reduce((sum, p) => sum + this.periodDueOf(p.id, period), 0));
    }
    return out;
  });
