46:     *  created first if it was never loaded; like the sheet's terms they apply to claims created
47:     *  from the from-date (null: the sheet's today) on (by the sheet's today, whatever their date), while every claim's due-by
48:     *  stays as it is. */
57:    /** Set a grade's grace days (null: none) from a date (null: the sheet's today), the sheet
58:     *  created first if it was never loaded; a claim dated from then on to the next from-date whose
59:     *  person's grade then is this one is overdue only once its due-by plus them is before the
60:     *  sheet's today, its late charge counted from there, so every live due (and every total) moves
61:     *  with them while every due-by and settled figure stays as it is. */
72:    /** The sheet's late percent: an overdue claim's due gains it for every full 30 days overdue. */
78:    /** Set the sheet's late percent from a date (null: the sheet's today), the sheet created first
79:     *  if it was never loaded; the late charge of every overdue OPEN claim with a 30-day boundary from
80:     *  then on to the next from-date (and so every total) moves with it, while settled figures stay. */
92:    /** The sheet's rounding mode in force on its today; null when there is none. */
98:    /** Set the sheet's rounding mode (half-up or half-even; null: none) from a date (null: the
99:     *  sheet's today), the sheet created first if it was never loaded; every live figure of a claim
100:     *  dated from then on to the next from-date (and so every total) rounds by it, a claim with none
101:     *  in force on its date by the policy date, while settled, bound and closed figures stay as they are. */
112:    /** The sheet's policy date as set; null when blank (the sheet's today is the policy date). */
118:    /** Set the sheet's policy date (null: blank, following the sheet's today), the sheet created
119:     *  first if it was never loaded; every live due's rounding (and so every total) moves with it,
120:     *  while settled and bound figures stay as they are. */
134:    /** The sheet's period numbering from-date; null when blank (off). */
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.key());
        return held;
    }

    /** Whether a user may settle a claim showing a due (null: n/a, within any limit) whose person
     *  has a grade on the sheet's today: a steward settles anything, a clerk only a due at or below
     *  the clerk limit in force (the grade's own when one is set, else the sheet's), if there is one. */
    @Transactional(readOnly = true)
    public boolean maySettle(String sheetId, String user, String grade, BigDecimal due) {
        if (due == null || roleOf(sheetId, user) == Role.STEWARD) {
            return true;
        }
        BigDecimal limit = sheets.find(sheetId).map(s -> s.clerkLimitFor(grade)).orElse(null);
        return limit == null || due.compareTo(limit) <= 0;
    }

    /** The roles the sheet's permission matrix sets for each action, as set; an action left blank
     *  (keeping its standing rule) is left out. */
    @Transactional(readOnly = true)
    public Map<Permission, String> permissions(String sheetId) {
        Map<Permission, String> out = new EnumMap<>(Permission.class);
        permissions.findBySheetId(sheetId).forEach(p -> out.put(p.getAction(), p.getRoles()));
        return out;
    }

    /** Set the roles that may take an action (blank: its standing rule), comma separated, the
     *  sheet created first if it was never loaded; not dated, it applies from now on. */
    @Transactional
    public String setPermission(String sheetId, String user, Permission action, String rolesText) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        SheetPermission held = permissions.findBySheetIdAndAction(sheetId, action.key()).orElse(null);
        if (rolesText.isEmpty()) {
            if (held != null) {
                permissions.delete(held);
            }
        } else if (held == null) {
            permissions.save(new SheetPermission(sheetId, action, rolesText));
        } else {
            held.setRoles(rolesText);
        }
        permissions.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                + " key=" + PERMISSION + action.key() + " value=" + rolesText);
        return rolesText;
    }

    /** Whether the user's role may take the action: as the permission matrix sets it, else by its
     *  standing rule. */
    @Transactional(readOnly = true)
    public boolean mayTake(String sheetId, String user, Permission action) {
        Role role = roleOf(sheetId, user);
        return permissions.findBySheetIdAndAction(sheetId, action.key())
                .map(p -> p.roleSet().contains(role))
                .orElseGet(() -> action.standing().contains(role));
    }

    /** Refuse (403) the action unless the user's role may take it. */
    @Transactional(readOnly = true)
    public void refuseUnlessAllowed(String sheetId, String user, Permission action) {
        if (!mayTake(sheetId, user, action)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user's role may not " + action.key() + " on this sheet");
        }
    }
}

